<?php
require_once __DIR__.'/../../includes/init.php';require_role('admin');require_once __DIR__.'/../../includes/layout.php';$pdo=db();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$act=(string)($_POST['action']??'');try{if(in_array($act,['add','update'],true)){$id=(int)($_POST['id_area']??0);$name=trim((string)($_POST['nama_area']??''));$cap=filter_var($_POST['kapasitas']??null,FILTER_VALIDATE_INT);if($name===''||mb_strlen($name)>50||$cap===false||$cap===null||$cap<1||$cap>100000)throw new InvalidArgumentException('Nama area wajib diisi dan kapasitas minimal 1.');if($act==='add')$pdo->prepare('INSERT INTO tb_area_parkir(nama_area,kapasitas,terisi) VALUES(?,?,0)')->execute([$name,$cap]);else{$s=$pdo->prepare('SELECT terisi FROM tb_area_parkir WHERE id_area=?');$s->execute([$id]);$occupied=$s->fetchColumn();if($occupied===false)throw new InvalidArgumentException('Area tidak ditemukan.');if($cap<(int)$occupied)throw new InvalidArgumentException('Kapasitas tidak boleh lebih kecil dari jumlah kendaraan terisi.');$pdo->prepare('UPDATE tb_area_parkir SET nama_area=?,kapasitas=? WHERE id_area=?')->execute([$name,$cap,$id]);}log_activity('Mengubah area parkir '.$name);flash('success','Data area berhasil disimpan. Jumlah terisi dihitung oleh transaksi, bukan diedit manual.');redirect('admin/area/index.php');}if($act==='delete'){$id=input_int('id_area');$s=$pdo->prepare('SELECT COUNT(*) FROM tb_transaksi WHERE id_area=?');$s->execute([$id]);if((int)$s->fetchColumn())throw new InvalidArgumentException('Area memiliki riwayat transaksi dan tidak dapat dihapus.');$pdo->prepare('DELETE FROM tb_area_parkir WHERE id_area=?')->execute([$id]);log_activity('Menghapus area ID '.$id);flash('success','Area dihapus.');redirect('admin/area/index.php');}throw new InvalidArgumentException('Aksi tidak valid.');}catch(Throwable $e){$error=$e instanceof InvalidArgumentException?$e->getMessage():(($e instanceof PDOException&&$e->getCode()==='23000')?'Nama area sudah digunakan.':'Operasi area gagal.');if(!($e instanceof InvalidArgumentException)&&!($e instanceof PDOException&&$e->getCode()==='23000'))error_log('[ParkirSTRD area] '.$e->getMessage());}}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM tb_area_parkir WHERE id_area=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch()?:null;}$rows=$pdo->query('SELECT a.*,(SELECT COUNT(*) FROM tb_transaksi t WHERE t.id_area=a.id_area AND t.status="masuk") AS aktif FROM tb_area_parkir a ORDER BY nama_area')->fetchAll();render_header('Manajemen Area Parkir','area');?>
<div class="page-intro"><div><h2>Area parkir</h2><p>Pantau kapasitas, kendaraan terisi, dan slot yang masih tersedia.</p></div></div><?php if($error): ?><div class="alert alert-error"><?= h($error) ?></div><?php endif; ?><section class="panel"><div class="panel-heading"><div><h2><?= $edit?'Edit area':'Tambah area' ?></h2><p>Nilai terisi tidak dapat diedit secara manual agar selalu sinkron.</p></div></div><form method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="<?= $edit?'update':'add' ?>"><?php if($edit): ?><input type="hidden" name="id_area" value="<?= (int)$edit['id_area'] ?>"><?php endif; ?><div class="field"><label>Nama area</label><input name="nama_area" maxlength="50" required value="<?= h($edit['nama_area']??'') ?>"></div><div class="field"><label>Kapasitas slot</label><input name="kapasitas" type="number" min="1" max="100000" step="1" required value="<?= h($edit['kapasitas']??'20') ?>"></div><div class="form-actions"><?php if($edit): ?><a class="btn btn-secondary" href="<?= h(url('admin/area/index.php')) ?>">Batal</a><?php endif; ?><button class="btn btn-primary"><?= $edit?'Simpan area':'Tambah area' ?></button></div></form></section><div class="area-grid"><?php foreach($rows as $r):$pct=(int)round((int)$r['terisi']/max(1,(int)$r['kapasitas'])*100);?><article class="area-card"><div class="area-top"><div><h3><?= h($r['nama_area']) ?></h3><div class="muted">Area #<?= (int)$r['id_area'] ?></div></div><span class="badge <?= $pct>=90?'badge-danger':($pct>=70?'badge-warning':'badge-success') ?>"><?= $pct>=90?'Hampir penuh':($pct>=70?'Ramai':'Tersedia') ?></span></div><div class="area-number" style="margin-top:15px"><?= (int)$r['terisi'] ?> <small>/ <?= (int)$r['kapasitas'] ?> slot</small></div><div class="progress"><span style="width:<?= min(100,$pct) ?>%;<?= $pct>=90?'background:#df596c':'' ?>"></span></div><div class="area-foot"><span><?= $pct ?>% terisi</span><span><?= max(0,(int)$r['kapasitas']-(int)$r['terisi']) ?> tersedia</span></div><div class="table-actions" style="margin-top:16px"><a class="btn btn-secondary btn-sm" href="<?= h(url('admin/area/index.php?edit='.(int)$r['id_area'])) ?>">Edit area</a><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id_area" value="<?= (int)$r['id_area'] ?>"><button class="btn btn-danger btn-sm" data-confirm="Hapus area ini? Riwayat transaksi harus kosong." <?= (int)$r['aktif']?'disabled':'' ?>>Hapus</button></form></div></article><?php endforeach; ?></div><?php render_footer(); ?>